const items = $input.all();
const validItems = [];
const invalidItems = [];

for (const item of items) {
  const errors = [];
  const props = item.json;

  // Check media file exists and is a valid URL
  const mediaFiles = props.property_media_file;
  if (!mediaFiles || !Array.isArray(mediaFiles) || mediaFiles.length === 0) {
    errors.push('Missing media file');
  } else {
    const url = mediaFiles[0]?.url || mediaFiles[0]?.external?.url || mediaFiles[0];
    if (!url || typeof url !== 'string' || !url.startsWith('http')) {
      errors.push('Invalid media file URL');
    }
  }

  // Check caption is non-empty
  const caption = props.property_caption;
  if (!caption || (typeof caption === 'string' && caption.trim() === '')) {
    errors.push('Caption is empty');
  }

  // YouTube title check
  const youtubeTitle = props.youtube_title || props.property_youtube_title || props.title;
  if (!youtubeTitle || (typeof youtubeTitle === 'string' && youtubeTitle.trim() === '')) {
    errors.push('Missing YouTube title (youtube_title or title required)');
  }

  // Caption length checks per platform
  const captionStr = typeof caption === 'string' ? caption : JSON.stringify(caption || '');
  if (captionStr.length > 2200) {
    errors.push(`Caption too long for Instagram (${captionStr.length}/2200)`);
  }
  if (captionStr.length > 4000) {
    errors.push(`Caption too long for TikTok (${captionStr.length}/4000)`);
  }
  if (captionStr.length > 500) {
    // Just a warning for Twitter, not blocking
  }

  if (errors.length > 0) {
    invalidItems.push({
      json: {
        ...props,
        validation_errors: errors,
        validation_error: errors.join('; ')
      }
    });
  } else {
    validItems.push(item);
  }
}

return [validItems, invalidItems];

