const item = $input.first();
const notionItem = $('Content Validation').first();
let enrichedCaptions = {};

try {
  const response = item.json;
  if (response.content && response.content[0] && response.content[0].text) {
    const text = response.content[0].text;
    // Try to parse JSON from the response
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      enrichedCaptions = JSON.parse(jsonMatch[0]);
    }
  }
} catch (e) {
  // Fallback: use master caption for all platforms
  enrichedCaptions = {};
}

const masterCaption = notionItem.json.property_caption || '';

return [{
  json: {
    ...notionItem.json,
    tiktok_caption: enrichedCaptions.tiktok_caption || masterCaption,
    instagram_caption: enrichedCaptions.instagram_caption || masterCaption,
    youtube_caption: enrichedCaptions.youtube_caption || masterCaption,
    threads_caption: enrichedCaptions.threads_caption || masterCaption,
    linkedin_caption: enrichedCaptions.linkedin_caption || masterCaption,
    twitter_caption: enrichedCaptions.twitter_caption || masterCaption,
    facebook_caption: enrichedCaptions.facebook_caption || masterCaption,
    pinterest_caption: enrichedCaptions.pinterest_caption || masterCaption,
    ai_enriched: Object.keys(enrichedCaptions).length > 0
  }
}];

const item = $input.first();
const platforms = ['tiktok', 'instagram', 'youtube', 'threads', 'linkedin', 'twitter', 'facebook', 'pinterest'];
const results = platforms.map(p => ({
  json: {
    platform: p,
    status: 'failed',
    error_message: 'Media upload failed: ' + (item.json.error || 'Unknown error'),
    master_page_id: item.json.id || '',
    content_title: item.json.title || item.json.property_title || 'Unknown',
    media_url: '',
    caption_used: '',
    workflow_execution_id: $execution.id
  }
}));
return results;

const results = $input.all().map(i => i.json);

for (const result of results) {
  const title = `${(result.platform || 'unknown').toUpperCase()} - ${(result.status || 'unknown').toUpperCase()} - ${result.content_title || 'Unknown'}`;
  const isFailure = result.status === 'failed';
  const now = new Date();
  const retryAt = new Date(now.getTime() + 30 * 60 * 1000);

  result._logEntry = {
    title: title,
    master_page_id: result.master_page_id || '',
    platform: result.platform || '',
    status: result.status || '',
    error_message: result.error_message || '',
    content_title: result.content_title || '',
    media_url: result.media_url || '',
    caption_used: (result.caption_used || '').substring(0, 200),
    retry_count: 0,
    retry_status: isFailure ? 'queued' : 'N/A',
    next_retry_at: isFailure ? retryAt.toISOString() : '',
    workflow_run_id: result.workflow_execution_id || '',
    timestamp: now.toISOString()
  };
}

return results.map(r => ({ json: r }));

const results = $input.all().map(i => i.json);

const successes = results.filter(r => r.status === 'success' || r._logEntry?.status === 'success');
const failures = results.filter(r => r.status === 'failed' || r._logEntry?.status === 'failed');

const failedPlatforms = failures.map(r => r.platform || r._logEntry?.platform).filter(Boolean);
const successPlatforms = successes.map(r => r.platform || r._logEntry?.platform).filter(Boolean);

let status;
if (failures.length === 0) {
  status = 'Posted';
} else if (successes.length === 0) {
  status = 'Failed';
} else {
  status = `Partial - ${failedPlatforms.join(', ')} failed`;
}

const platformResults = {};
for (const r of results) {
  const p = r.platform || r._logEntry?.platform;
  if (p) {
    platformResults[p] = {
      status: r.status || r._logEntry?.status,
      error: r.error_message || r._logEntry?.error_message || null
    };
  }
}

return [{
  json: {
    calculated_status: status,
    platform_results: JSON.stringify(platformResults),
    failed_platforms: failedPlatforms,
    success_platforms: successPlatforms,
    has_failures: failures.length > 0,
    master_page_id: results[0]?.master_page_id || results[0]?._logEntry?.master_page_id || '',
    content_title: results[0]?.content_title || results[0]?._logEntry?.content_title || '',
    all_results: results,
    failure_details: failures.map(f => ({
      platform: f.platform || f._logEntry?.platform,
      error: f.error_message || f._logEntry?.error_message
    }))
  }
}];

